@Component("aircraftProgram-handler")
@ProcessingGroup("aircraftProgram-processing-group")
public class AircraftProgramEventHandler {
	
	// core constructor
	AircraftProgramEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAircraftProgramEvent
     */
    @EventHandler
    public void handle( CreateAircraftProgramEvent event) {
        entityManager.persist(new AircraftProgram(event.getAircraftProgramId(), event.getName(), event.getProgramCode(), event.getEntryIntoServiceYear(), event.getManufacturer(), event.getAircraftFamilies(), event.getTypeCertificate(), event.getKeySuppliers(), event.getStatus()));
    }

    /*
     * @param	event UpdateAircraftProgramEvent
     */
    @EventHandler
    public AircraftProgram handle( UpdateAircraftProgramEvent event) {
    	entityManager.merge(new AircraftProgram(event.getAircraftProgramId(), event.getName(), event.getProgramCode(), event.getEntryIntoServiceYear(), event.getManufacturer(), event.getAircraftFamilies(), event.getTypeCertificate(), event.getKeySuppliers(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteAircraftProgramEvent
     */
    @EventHandler
    public void on( DeleteAircraftProgramEvent event) {
    	AircraftProgram entity = new AircraftProgram();
   
    	// ------------------------------------------
    	// apply the AircraftProgramId
    	// ------------------------------------------
    	entity.setAircraftProgramId( event.getAircraftProgramId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AircraftProgramRepository aircraftProgramEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AircraftProgramEventHandler.class.getName());

}
